#!/usr/bin/env python3
# SPDX-License-Identifier: LGPL-3.0-or-later
"""Compare legacy GridFT models using voltage tables generated by CASA."""

import argparse
import json
from pathlib import Path
from tempfile import TemporaryDirectory

import casatasks
from casatools import componentlist, imager as casa_imager, measures, table, vpmanager
import numpy as np

from calibration_ft_oracle import coordinates
from gaincal_oracle import relative_rms
from imager_component_voltage_oracle import compare, predict, scratch_pair, source
from imager_custom_squint_oracle import saved_exchange
from imager_legacy_pbw_oracle import data, make_input
from imager_legacy_squint_oracle import fourier_grid, shifted_tangent_model


SHAPES = {
    'polynomial': ('setpbpoly', {'coeff': [1., -.0025, .000002]}),
    'inverse': ('setpbinvpoly', {'coeff': [1., .004, .00002]}),
    'cosines': ('setpbcospoly', {'coeff': [.83, .17], 'scale': [.05, .07]}),
    'samples': ('setpbnumeric', {'vect': [1., .89, .73, .48, .27, .1]}),
}


def voltage_table(path, name, *, is_voltage=False, squint=False):
    maker = vpmanager()
    maker.reset()
    method, values = SHAPES[name]
    options = dict(telescope='VLA', maxrad='1500arcsec', reffreq='1.4GHz',
                   isthispb='VP' if is_voltage else 'PB')
    if squint:
        me = measures()
        options.update(dosquint=True, squintreffreq='0.7GHz',
                       squintdir=me.direction('J2000', '-180arcsec', '72arcsec'))
    record = getattr(maker, method)(**options, **values)
    assert record['isthisvp'] == is_voltage
    assert maker.saveastable(str(path))
    reader = table()
    assert reader.open(str(path))
    stored = reader.getcell('pbdescription', 0)
    assert stored['name'] == record['name'] and stored['isthisvp'] == is_voltage
    for key, vector in values.items():
        np.testing.assert_array_equal(stored[key], vector)
    assert reader.done()


def frequency_fits(path):
    voltage_table(path, 'inverse')
    updater = table()
    assert updater.open(str(path), nomodify=False)
    record = updater.getcell('pbdescription', 0)
    record['fitfreqs'] = np.array([1.2e9, 1.47e9, 1.8e9])
    record['coeff'] = np.array([
        [1., .001, .00001, 0.],
        [1., .004, .00002, 0.],
        [1., .009, .00004, 0.],
    ]).T
    assert updater.putcell('pbdescription', 0, record) and updater.done()


def check_negative_power(work, seed, point, results):
    outer = work / 'outer.cl'
    ra, dec = coordinates(seed)
    frequency = data(seed / 'SPECTRAL_WINDOW', 'CHAN_FREQ')[0, 0]
    offset = np.radians(33. / 60.) / (frequency / 1.e9)
    sky = componentlist()
    assert sky.addcomponent(dir=f'J2000 {ra}rad {dec + offset}rad', flux=3.7, freq='1.55GHz')
    assert sky.rename(str(outer)) and sky.done()
    for name, coeff in (('crossing', [1., -.001]), ('flat', [1.])):
        curve = work / f'{name}.tbl'
        manager = vpmanager()
        manager.reset()
        assert manager.setpbpoly(telescope='VLA', coeff=coeff, maxrad='1500arcsec', reffreq='1.4GHz')
        assert manager.saveastable(str(curve))
        inner = scratch_pair(work, seed, point, results, f'{name}-inner', vptable=curve, spw='0:0')
        far = scratch_pair(work, seed, outer, results, f'{name}-outer', vptable=curve, spw='0:0')
        assert np.abs(inner[:, 0, :]).max() > 2.
        if name == 'crossing':
            assert not np.any(far[:, 0, :])
        else:
            assert np.abs(far[:, 0, :]).max() > 3.


def check_projected_image(work, seed, model, beam, results):
    from casars.tools import imager as native_imager

    shifted = work / 'shifted-tangent.im'
    shifted_tangent_model(model, shifted)
    scratch_pair(work, seed, None, results, 'inverse-image-projected', model=shifted,
                 vptable=beam, spw='0:0')
    grids = []
    for label, factory in [('casa', casa_imager), ('native', native_imager)]:
        path = work / f'{label}-shifted-saved.ms'
        make_input(seed, path, scratch=False)
        predict(factory, path, None, model=shifted, scratch=False, vptable=beam, spw='0:0')
        grids.append(fourier_grid(path))
    assert np.max(np.abs(grids[0])) > .4
    compare(results, 'inverse-image-projected-grid', grids[1], grids[0])


def run(root, seed, model):
    assert casatasks.version_string() == '6.7.6.14'
    root.mkdir(parents=True, exist_ok=True)
    results = {}
    with TemporaryDirectory(dir=root) as attempt:
        work = Path(attempt)
        point = work / 'off-axis.cl'
        source(point, seed, [3.7, .4, -.6, -.8])
        unattenuated = scratch_pair(work, seed, point, results, 'unattenuated-point', beam=False)
        blank_beam = scratch_pair(work, seed, None, results, 'unattenuated-image', model=model,
                                  beam=False)
        for name in SHAPES:
            power, voltage = work / f'{name}.tbl', work / f'{name}-voltage.tbl'
            voltage_table(power, name)
            voltage_table(voltage, name, is_voltage=True)
            result = scratch_pair(work, seed, point, results, f'{name}-point-pb', vptable=power)
            assert relative_rms(result, unattenuated) > .08
            image = scratch_pair(work, seed, None, results, f'{name}-image-pb', model=model,
                                 vptable=power)
            assert relative_rms(image, blank_beam) > .08
            vp = scratch_pair(work, seed, point, results, f'{name}-point-vp', vptable=voltage)
            assert relative_rms(vp, result) > .06
        multiband = work / 'inverse-frequency.tbl'
        frequency_fits(multiband)
        varied = scratch_pair(work, seed, point, results, 'inverse-frequency-point',
                              vptable=multiband)
        assert relative_rms(varied, unattenuated) > .1
        scratch_pair(work, seed, None, results, 'inverse-frequency-image', model=model,
                     vptable=multiband)
        check_negative_power(work, seed, point, results)
        check_projected_image(work, seed, model, work / 'inverse.tbl', results)
        squint = work / 'polynomial-squint.tbl'
        voltage_table(squint, 'polynomial', squint=True)
        live = scratch_pair(work, seed, None, results, 'polynomial-squint-image', model=model,
                            vptable=squint, squint=True)
        scratch_pair(work, seed, point, results, 'polynomial-squint-point',
                     squint=True, vptable=squint)
        saved_exchange(work, seed, [
            ('polynomial-point', point, None, unattenuated),
            ('polynomial-image', None, model, live),
        ], squint, results)
    (root / 'results.json').write_text(json.dumps(results, indent=2) + '\n')


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    for name in ('work', 'dataset', 'model'):
        parser.add_argument(f'--{name}', type=Path, required=True)
    args = parser.parse_args()
    run(args.work.resolve(), args.dataset.resolve(), args.model.resolve())
